using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using UnityEngine;
using UnityEngine.Rendering.Universal;
namespace FootballDynasty {
 public sealed class FootballSimulator:MonoBehaviour {
  public TeamTactics Tactics;public BroadcastCamera Broadcast;private MatchInput matchInput;public MatchReplay Replay;private Vector3 previousBall;public Career Career;public string ClubId="madrid";public string Screen="career";public string Status="";
  public readonly List<FootballAgent> Agents=new List<FootballAgent>();public Rigidbody Ball;public FootballAgent Controlled;
  public Camera MatchCamera;public MatchResult ActiveFixture;public float Clock;public bool Running,Finished;public int HomeGoals,AwayGoals;
  private Transform world;private float kickoffDelay;private Vector3 direction;private bool sprint;private GUIStyle title,cardStyle;private Vector2 scroll;private string query="";private int selectedSlot=-1,page;private Player offer;
  private string SavePath=>Path.Combine(Application.persistentDataPath,"career-unity-v1.json");
  void Awake(){if(!GetComponent<QualityManager>())gameObject.AddComponent<QualityManager>();var asset=Resources.Load<TextAsset>("database-2026");if(!asset){Debug.LogError("Falta la base 2026/27.");enabled=false;return;}Career=new Career(JsonUtility.FromJson<Database>(asset.text));if(File.Exists(SavePath)){try{Career.Restore(JsonUtility.FromJson<CareerSave>(File.ReadAllText(SavePath)));}catch(Exception e){Status="No se cargó el guardado: "+e.Message;}}if(Career.Coach!=null)ClubId=Career.ManagedClub;CreateWorld();CameraSetup();Replay=gameObject.AddComponent<MatchReplay>();Replay.Initialize(this);Tactics=gameObject.AddComponent<TeamTactics>();Tactics.Initialize(this);Broadcast=gameObject.AddComponent<BroadcastCamera>();Broadcast.Initialize(this);var mobile=gameObject.AddComponent<MobileMatchUI>();mobile.Initialize(this);matchInput=gameObject.AddComponent<MatchInput>();matchInput.Configure(mobile);if(Career.Coach==null)gameObject.AddComponent<CoachOnboarding>().Initialize(this);}
  bool Save(){try{var text=JsonUtility.ToJson(Career.Snapshot(),true);Directory.CreateDirectory(Application.persistentDataPath);File.WriteAllText(SavePath+".tmp",text);File.Copy(SavePath+".tmp",SavePath,true);File.Delete(SavePath+".tmp");return true;}catch(Exception e){Status="No se pudo guardar: "+e.Message;return false;}}
  public bool FinishManagerSetup(CoachProfile profile,string club){Career.AssignCoach(profile,club);ClubId=club;var crowd=GetComponent<StadiumCrowd>();if(crowd)crowd.SetColors(ColorOf(club));if(!Save())return false;Screen="career";Status="Bienvenido, "+Career.Coach.DisplayName+".";return true;}
  public Material Material(Color color){var shader=Shader.Find("Universal Render Pipeline/Lit");if(!shader)shader=Shader.Find("Standard");var template=Resources.Load<Material>("DynastyLit");var m=template?new Material(template):new Material(shader);m.color=color;m.enableInstancing=true;m.SetFloat("_Smoothness",.2f);return m;}
  GameObject Shape(PrimitiveType type,Vector3 at,Vector3 scale,Color color,bool collider=false){var g=GameObject.CreatePrimitive(type);g.transform.SetParent(world);g.transform.position=at;g.transform.localScale=scale;g.GetComponent<Renderer>().sharedMaterial=Material(color);if(!collider)Destroy(g.GetComponent<Collider>());return g;}
  Color ColorOf(string id){ColorUtility.TryParseHtmlString(Career.Clubs[id].color,out var c);return c;}
  void CreateWorld(){world=new GameObject("Estadio · Football Dynasty").transform;var grass=Material(new Color(.09f,.26f,.12f));var tex=new Texture2D(128,128);var rng=new System.Random(27);for(int y=0;y<128;y++)for(int x=0;x<128;x++){float noise=(float)rng.NextDouble()*.05f;tex.SetPixel(x,y,new Color(.3f+noise,.7f+noise,.32f+noise));}tex.Apply();tex.wrapMode=TextureWrapMode.Repeat;grass.SetTexture("_BaseMap",tex);grass.SetTextureScale("_BaseMap",new Vector2(32,22));var field=Shape(PrimitiveType.Cube,new Vector3(0,-.3f,0),new Vector3(160,.6f,120),Color.green,true);field.GetComponent<Renderer>().sharedMaterial=grass;
   gameObject.AddComponent<StadiumTurf>().Create(world);
   foreach(float z in new[]{-34f,34f})Shape(PrimitiveType.Cube,new Vector3(0,.03f,z),new Vector3(105,.03f,.12f),Color.white);
   foreach(float x in new[]{-52.5f,0,52.5f})Shape(PrimitiveType.Cube,new Vector3(x,.03f,0),new Vector3(.12f,.03f,68),Color.white);
   for(int i=0;i<72;i++){float a=i*Mathf.PI/36;var line=Shape(PrimitiveType.Cube,new Vector3(Mathf.Cos(a)*9.15f,.035f,Mathf.Sin(a)*9.15f),new Vector3(.85f,.025f,.1f),Color.white);line.transform.rotation=Quaternion.Euler(0,-a*Mathf.Rad2Deg+90,0);}
   foreach(int side in new[]{-1,1}){foreach(float z in new[]{-20.16f,20.16f})Shape(PrimitiveType.Cube,new Vector3(side*44.25f,.03f,z),new Vector3(16.5f,.03f,.12f),Color.white);Shape(PrimitiveType.Cube,new Vector3(side*36,.03f,0),new Vector3(.12f,.03f,40.32f),Color.white);foreach(float z in new[]{-3.66f,3.66f})Shape(PrimitiveType.Cube,new Vector3(side*52.5f,1.22f,z),new Vector3(.12f,2.44f,.12f),Color.white,true);Shape(PrimitiveType.Cube,new Vector3(side*52.5f,2.44f,0),new Vector3(.12f,.12f,7.32f),Color.white,true);for(float z=-3.6f;z<3.7f;z+=.3f)Shape(PrimitiveType.Cube,new Vector3(side*55,1.22f,z),new Vector3(.025f,2.44f,.025f),new Color(.65f,.7f,.7f));for(float y=.3f;y<2.4f;y+=.3f)Shape(PrimitiveType.Cube,new Vector3(side*55,y,0),new Vector3(.025f,.025f,7.32f),Color.gray);}
   for(int stand=0;stand<4;stand++){bool longitudinal=stand<2;int sign=stand%2==0?-1:1;float length=longitudinal?116:73;for(int row=0;row<12;row++){float depth=(longitudinal?39:60)+row*1.3f;Shape(PrimitiveType.Cube,longitudinal?new Vector3(0,row*.8f,sign*depth):new Vector3(sign*depth,row*.8f,0),longitudinal?new Vector3(length,.8f,1.3f):new Vector3(1.3f,.8f,length),new Color(.22f,.27f,.31f));}float outer=longitudinal?55:76;Shape(PrimitiveType.Cube,longitudinal?new Vector3(0,15,sign*outer):new Vector3(sign*outer,15,0),longitudinal?new Vector3(length,18,.7f):new Vector3(.7f,18,length),new Color(.23f,.27f,.3f));Shape(PrimitiveType.Cube,longitudinal?new Vector3(0,24,sign*(outer-3)):new Vector3(sign*(outer-3),24,0),longitudinal?new Vector3(length,.35f,8):new Vector3(8,.35f,length),new Color(.45f,.51f,.56f));}
   gameObject.AddComponent<StadiumCrowd>().Initialize(this,ColorOf(ClubId));var sun=new GameObject("Sol").AddComponent<Light>();sun.type=LightType.Directional;sun.intensity=1.2f;sun.color=new Color(1,.94f,.82f);sun.shadows=LightShadows.Soft;sun.transform.rotation=Quaternion.Euler(42,-28,0);RenderSettings.ambientMode=UnityEngine.Rendering.AmbientMode.Trilight;RenderSettings.ambientSkyColor=new Color(.45f,.57f,.7f);RenderSettings.ambientEquatorColor=new Color(.23f,.3f,.37f);RenderSettings.ambientGroundColor=new Color(.12f,.15f,.1f);RenderSettings.fog=true;RenderSettings.fogColor=new Color(.62f,.7f,.72f);RenderSettings.fogMode=FogMode.ExponentialSquared;RenderSettings.fogDensity=.0025f;gameObject.AddComponent<StadiumLighting>().Configure(sun);
  }
  void CameraSetup(){MatchCamera=Camera.main;if(!MatchCamera)MatchCamera=new GameObject("Cámara televisiva").AddComponent<Camera>();MatchCamera.tag="MainCamera";MatchCamera.transform.position=new Vector3(0,30,44);MatchCamera.transform.LookAt(Vector3.zero);MatchCamera.fieldOfView=55;MatchCamera.nearClipPlane=.1f;MatchCamera.farClipPlane=350;MatchCamera.backgroundColor=new Color(.55f,.66f,.75f);MatchCamera.allowHDR=!Application.isMobilePlatform;var cameraData=MatchCamera.GetUniversalAdditionalCameraData();cameraData.renderShadows=true;cameraData.renderPostProcessing=!Application.isMobilePlatform;}
  public void StartMatch(){var league=Career.Data.leagues.FirstOrDefault(l=>l.clubs.Contains(ClubId));if(league==null){Status="Este club es propietario de jugadores externos; no participa en las seis ligas.";return;}var pair=Career.NextLeague(league.id).FirstOrDefault(p=>p.Contains(ClubId));if(pair==null){Status="No hay partido de liga pendiente.";return;}Replay.NewMatch();ActiveFixture=new MatchResult{home=pair[0],away=pair[1],competition=league.id};foreach(var a in Agents)Destroy(a.gameObject);Agents.Clear();if(Ball)Destroy(Ball.gameObject);for(int team=0;team<2;team++){string id=team==0?pair[0]:pair[1];var ids=Career.Team(id).lineup;for(int i=0;i<ids.Length;i++){var agent=new GameObject(Career.Players[ids[i]].name).AddComponent<FootballAgent>();agent.Initialize(this,Career.Players[ids[i]],team,i,ColorOf(id));Agents.Add(agent);}}
   var ball=GameObject.CreatePrimitive(PrimitiveType.Sphere);ball.name="Balón · 430 gramos";ball.transform.localScale=Vector3.one*.22f;ball.GetComponent<Renderer>().sharedMaterial=FootballAppearance.BallMaterial(this);Ball=ball.AddComponent<Rigidbody>();ball.AddComponent<BallAerodynamics>().Initialize(this);Ball.mass=.43f;Ball.linearDamping=.12f;Ball.angularDamping=.05f;Ball.collisionDetectionMode=CollisionDetectionMode.ContinuousDynamic;Ball.interpolation=RigidbodyInterpolation.Interpolate;var pm=new PhysicsMaterial("Balón"){bounciness=.55f,dynamicFriction=.3f,staticFriction=.3f};ball.GetComponent<SphereCollider>().sharedMaterial=pm;Clock=0;HomeGoals=AwayGoals=0;Running=true;Finished=false;Screen="match";Kickoff(0);}
  void Kickoff(int team){Tactics.ResetPossession();foreach(var a in Agents)a.ResetPosition();var striker=Agents.First(a=>a.Team==team&&a.Data.position=="DEL");striker.Body.position=new Vector3(team==0?-1:1,.95f,0);Ball.position=new Vector3(0,.2f,0);Ball.linearVelocity=Vector3.zero;Ball.angularVelocity=Vector3.zero;kickoffDelay=1;Controlled=Agents.First(a=>a.Data.club==ClubId&&a.Data.position=="DEL");previousBall=Ball.position;}
  void Update(){if(!Running||Replay.IsPlaying)return;var input=matchInput.Read(MatchCamera);direction=input.Movement;sprint=input.Sprint;if(input.Switch)Controlled=Agents.Where(a=>a.Data.club==ClubId&&a.Data.position!="POR").OrderBy(a=>Vector3.Distance(a.transform.position,Ball.position)).First();if(input.Shoot)Controlled.Kick(false);if(input.Pass)Controlled.Kick(true);if(input.Pause)Time.timeScale=Time.timeScale==0?1:0;}
  void FixedUpdate(){if(!Running||Replay.IsPlaying)return;Clock+=Time.fixedDeltaTime;kickoffDelay=Mathf.Max(0,kickoffDelay-Time.fixedDeltaTime);if(kickoffDelay<=0){Tactics.Tick(Time.fixedDeltaTime);foreach(var a in Agents)a.Step(a==Controlled?direction:Vector3.zero,a==Controlled,a==Controlled?sprint:a.Decision.Sprint);}var ballAt=Ball.position;int goal=GoalRules.CrossedGoal(previousBall.x,previousBall.y,previousBall.z,ballAt.x,ballAt.y,ballAt.z);if(goal!=0){if(goal>0)HomeGoals++;else AwayGoals++;Replay.Record();Replay.Goal();Kickoff(goal>0?1:0);}else{Replay.Record();if(Mathf.Abs(Ball.position.x)>52.65f){var keeper=Agents.First(a=>a.Team==(Ball.position.x>0?1:0)&&a.Data.position=="POR");Ball.position=keeper.transform.position+Vector3.up*.3f;Ball.linearVelocity=Vector3.zero;}}if(Mathf.Abs(Ball.position.z)>34.3f){var pos=Ball.position;pos.z=Mathf.Clamp(pos.z,-33,33);Ball.position=pos;Ball.linearVelocity*=.25f;}previousBall=Ball.position;if(Clock>=180){Running=false;Finished=true;ActiveFixture.hg=HomeGoals;ActiveFixture.ag=AwayGoals;Time.timeScale=1;}}

  void InitStyles(){if(title!=null)return;title=new GUIStyle(GUI.skin.label){fontSize=22,fontStyle=FontStyle.Bold};cardStyle=new GUIStyle(GUI.skin.box){alignment=TextAnchor.UpperLeft,fontSize=14,padding=new RectOffset(10,10,10,8),wordWrap=true};}
  void Card(Player p,Action pick,bool selected=false){var old=GUI.backgroundColor;GUI.backgroundColor=p.legend?new Color(.65f,.5f,.2f):selected?new Color(.45f,.65f,.34f):new Color(.14f,.34f,.27f);GUILayout.BeginVertical(GUI.skin.box,GUILayout.Width(145),GUILayout.Height(160));GUILayout.Label(p.rating+" · "+p.position,title);GUILayout.Label(p.name);GUILayout.Label($"{p.stats.RIT} RIT   {p.stats.TIR} TIR   {p.stats.PAS} PAS\n{p.stats.REG} REG   {p.stats.DEF} DEF   {p.stats.FIS} FIS");GUILayout.Label(p.legend?"LEYENDA HISTÓRICA":Career.Clubs[p.club].name);if(GUILayout.Button(selected?"Titular":"Seleccionar"))pick();GUILayout.EndVertical();GUI.backgroundColor=old;}
  void OnGUI(){if(Career==null||Replay.IsPlaying||Screen=="replays"||Screen=="onboarding")return;InitStyles();GUI.matrix=Matrix4x4.TRS(Vector3.zero,Quaternion.identity,new Vector3(ScreenWidth/1280f,ScreenHeight/720f,1));GUILayout.BeginArea(new Rect(15,12,1250,Screen=="match"?220:695),GUI.skin.box);GUILayout.Label("FOOTBALL DYNASTY 27 · UNITY",title);if(Screen=="match"){GUILayout.Label($"{Career.Clubs[ActiveFixture.home].name}  {HomeGoals} : {AwayGoals}  {Career.Clubs[ActiveFixture.away].name} · {Mathf.FloorToInt(Clock/2)}′");GUILayout.Label("WASD mover · Shift correr · J/B pase · K/A tiro · L/C cambiar · P pausa");GUILayout.Label("DYNASTY IQ · Fase: "+Tactics.Possession.PhaseFor(ActiveFixture.home==ClubId?0:1)+(Controlled?" · "+Controlled.Role:""));Replay.MatchButtons();if(Finished&&GUILayout.Button("Guardar resultado y continuar carrera")){Career.Advance(ActiveFixture);Save();Finished=false;Screen="career";}if(GUILayout.Button("Salir sin guardar el partido")){Running=false;Finished=false;Time.timeScale=1;Screen="career";}GUILayout.EndArea();return;}
   GUILayout.BeginHorizontal();foreach(var screen in new[]{"career","clubs","squad","market","competitions"})if(GUILayout.Button(new Dictionary<string,string>{{"career","Carrera"},{"clubs","Elegir club"},{"squad","Once y cartas"},{"market","Fichajes"},{"competitions","Ligas y torneos"}}[screen])){Screen=screen;scroll=Vector2.zero;}GUILayout.EndHorizontal();GUILayout.Label(Career.Clubs[ClubId].name+$" · € {Career.Clubs[ClubId].budget/1000000:F1} M · Temporada {Career.Season}/{Career.Season+1} · Jornada {Math.Min(Career.Round+1,40)}/40");GUILayout.Label(Status);scroll=GUILayout.BeginScrollView(scroll);
   if(Screen=="career"){if(Career.Coach!=null)GUILayout.Label("DT · "+Career.Coach.DisplayName+" · "+Career.Coach.country,title);if(GUILayout.Button("Repeticiones guardadas"))Replay.OpenGallery();GUILayout.Label("Simulación física 11 contra 11. El partido de liga jugado se incorpora al calendario.");if(!Career.SeasonFinished&&GUILayout.Button("Jugar próximo partido"))StartMatch();if(Career.SeasonFinished&&GUILayout.Button("Iniciar siguiente temporada")){Career.StartNextSeason();Save();Status="Nueva temporada: se conservan fichajes, fondos y once.";}if(GUILayout.Button("Simular jornada")){try{Career.Advance();Save();}catch(Exception e){Status=e.Message;}}GUILayout.Label("Guardado: "+SavePath);}
   if(Screen=="clubs")foreach(var league in Career.Data.leagues){GUILayout.Label(league.name,title);GUILayout.BeginHorizontal();int i=0;foreach(var id in league.clubs){if(i++%5==0&&i>1){GUILayout.EndHorizontal();GUILayout.BeginHorizontal();}if(GUILayout.Button(Career.Clubs[id].name,GUILayout.Width(220))){ClubId=id;Career.ManagedClub=id;Save();selectedSlot=-1;Screen="career";FindObjectOfType<StadiumCrowd>().SetColors(ColorOf(id));}}GUILayout.EndHorizontal();}
   if(Screen=="squad"){foreach(var f in Career.Formations.Keys)if(GUILayout.Button(f,GUILayout.Width(100))){Career.SetFormation(ClubId,f);Save();}var t=Career.Team(ClubId);GUILayout.Label("Pulsa un titular y después su sustituto. Formación: "+t.formation);for(int i=0;i<t.lineup.Length;i++){if(i%6==0)GUILayout.BeginHorizontal();int slot=i;Card(Career.Players[t.lineup[i]],()=>selectedSlot=slot,selectedSlot==slot);if(i%6==5||i==t.lineup.Length-1)GUILayout.EndHorizontal();}GUILayout.Label("DYNASTY IQ · Roles del once",title);foreach(var playerId in t.lineup){var member=Career.Players[playerId];GUILayout.BeginHorizontal();GUILayout.Label(member.name,GUILayout.Width(260));if(GUILayout.Button(Career.GetRole(playerId).ToString(),GUILayout.Width(280))){var options=((TacticalRole[])Enum.GetValues(typeof(TacticalRole))).Where(r=>member.position=="POR"?r==TacticalRole.Portero:r!=TacticalRole.Portero).ToArray();var current=Array.IndexOf(options,Career.GetRole(playerId));Career.SetRole(ClubId,playerId,options[(current+1)%options.Length]);Save();}GUILayout.EndHorizontal();}GUILayout.Label("Plantilla",title);var squad=Career.Squad(ClubId).Where(p=>selectedSlot<0||p.position==Career.Players[t.lineup[selectedSlot]].position).ToArray();for(int i=0;i<squad.Length;i++){if(i%6==0)GUILayout.BeginHorizontal();var p=squad[i];Card(p,()=>{if(selectedSlot>=0&&Career.SetSlot(ClubId,selectedSlot,p.id)){Status=p.name+" entra en el once.";Save();}});if(i%6==5||i==squad.Length-1)GUILayout.EndHorizontal();}}
   if(Screen=="market"){query=GUILayout.TextField(query);var matches=Career.Data.players.Where(p=>p.club!=ClubId&&(query.Length==0||p.name.IndexOf(query,StringComparison.OrdinalIgnoreCase)>=0)).OrderByDescending(p=>p.name=="Lionel Messi"||p.name=="Cristiano Ronaldo"?1000:p.legend?500:p.rating).ToArray();GUILayout.BeginHorizontal();if(GUILayout.Button("Anterior"))page=Math.Max(0,page-1);if(GUILayout.Button("Siguiente"))page++;GUILayout.EndHorizontal();page=Math.Min(page,Math.Max(0,(matches.Length-1)/18));var list=matches.Skip(page*18).Take(18).ToArray();for(int i=0;i<list.Length;i++){if(i%6==0)GUILayout.BeginHorizontal();var p=list[i];Card(p,()=>offer=p);if(i%6==5||i==list.Length-1)GUILayout.EndHorizontal();}if(offer!=null){GUILayout.Label($"Comprar {offer.name} a {Career.Clubs[offer.club].name} por € {(offer.value+offer.wage*4)/1000000:F2} M (incluye prima)");if(GUILayout.Button("Confirmar oferta al propietario")){var result=Career.Buy(offer.id,ClubId,offer.club);Status=result.Message;if(result.Ok)Save();offer=null;}}}
   if(Screen=="competitions"){foreach(var league in Career.Data.leagues){GUILayout.Label(league.name,title);foreach(var row in Career.Table(league.clubs,Career.Results.Where(m=>m.competition==league.id)))GUILayout.Label($"{Career.Clubs[row.Club].name,-30}  PJ {row.Played}   Pts {row.Points}   GF {row.GF}   GC {row.GA}");}foreach(var cup in Career.Tournaments){GUILayout.Label(cup.name+" · "+cup.stage,title);if(!string.IsNullOrEmpty(cup.champion))GUILayout.Label("Campeón: "+Career.Clubs[cup.champion].name);foreach(var m in cup.games.TakeLastCompat(12))GUILayout.Label($"{Career.Clubs[m.home].name}  {m.hg}:{m.ag}  {Career.Clubs[m.away].name}");}}
   GUILayout.EndScrollView();GUILayout.EndArea();}
  int ScreenWidth=>UnityEngine.Screen.width;int ScreenHeight=>UnityEngine.Screen.height;
 }
 public static class ListExtensions {public static IEnumerable<T> TakeLastCompat<T>(this IEnumerable<T> source,int n){var a=source.ToArray();return a.Skip(Math.Max(0,a.Length-n));}}
}
